gFy(){return"\u043f\u0440\u0438\u0439\u043c\u0435\u043d\u043d\u0438\u043a"},
gF5(){return"\u043e\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439 \u0430\u0440\u0442\u0438\u043a\u043b\u044c"},
gFv(){return"\u0444\u0440\u0430\u0437\u0430 (\u0456\u0434\u0456\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u0438\u0439 \u0432\u0438\u0440\u0430\u0437)"},
