gN_(){return u.R},
gN1(){return"\u0412 \u0434\u0430\u043d\u0438\u0439 \u0447\u0430\u0441 \u041f\u0430\u043f\u0456\u0440\u0443\u0441 85 \u0437\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c\u0441\u044f \u0432 \u041d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u0456\u0439 \u0430\u043a\u0430\u0434\u0435\u043c\u0456\u0447\u043d\u0456\u0439 \u0431\u0456\u0431\u043b\u0456\u043e\u0442\u0435\u0446\u0456 \u0432 \u0421\u0442\u0440\u0430\u0441\u0431\u0443\u0440\u0437\u0456, \u0424\u0440\u0430\u043d\u0446\u0456\u044f."},
